STUDIO_TABLES = (
    "StudioProfile",
    "TrendSource",
    "TrendItem",
    "ContentIdea",
    "ContentPiece",
    "StudioRun",
)


def give_existing_data_a_brand(apps, schema_editor):
    """Everything the studio kept so far belonged to the workspace; it now belongs to one brand
    named after the workspace, so nothing is lost and nothing changes for the owner."""
    from django.utils.text import slugify

    Brand = apps.get_model("studio", "Brand")
    Workspace = apps.get_model("workspaces", "Workspace")
    for workspace in Workspace.objects.all():
        rows = [apps.get_model("studio", name).objects.filter(workspace_id=workspace.pk) for name in STUDIO_TABLES]
        if not any(r.exists() for r in rows):
            continue
        brand, _ = Brand.objects.get_or_create(
            workspace_id=workspace.pk,
            slug=slugify(workspace.name)[:80] or "main",
            defaults={"name": workspace.name[:120]},
        )
        for r in rows:
            r.filter(brand__isnull=True).update(brand_id=brand.pk)


